SELECT EXISTS (
    SELECT 1
      FROM broadcast_sessions
     WHERE streamer_id = #{streamerId}
       AND status IN ('PREPARING', 'LIVE')
)

SELECT 
  FROM broadcast_sessions
 WHERE id = #{sessionId}
   AND streamer_id = #{streamerId}
 FOR UPDATE

mapper.update:
UPDATE broadcast_sessions
   SET status = 'ENDED',
       ended_at = #{endedAt}
 WHERE id = #{sessionId}
   AND status IN ('PREPARING', 'LIVE')

UPDATE broadcast_sessions
   SET status = 'FAILED',
       ended_at = #{failedAt}
 WHERE id = #{sessionId}
   AND status IN ('PREPARING', 'LIVE')

UPDATE calendar_events
   SET status = 'COMPLETED'
 WHERE id = #{calendarEventId}
   AND streamer_id = #{streamerId}
   AND event_type = 'BROADCAST'
   AND status = 'SCHEDULED'

