SELECT 
  FROM broadcast_sessions s
 WHERE s.id = #{sessionId}
   AND s.streamer_id = #{streamerId}

SELECT s.id AS session_id, s.title, s.category, s.thumbnail_url, s.status, s.started_at, s.ended_at, r.status AS report_status FROM broadcast_sessions s LEFT JOIN reports r ON r.session_id = s.id WHERE s.streamer_id = #{streamerId}
AND s.status = #{status}
ORDER BY s.started_at DESC, s.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT count(*)
  FROM broadcast_sessions
 WHERE streamer_id = #{streamerId}

   AND status = #{status}

